// n8n Code Node
const input = $input.first().json.body.combatPlan.targetInfo;

function parseLocation(input) {
    // Check if input is already a structured object
    if (typeof input === 'object' && input !== null) {

        // Handle nested coordinates: { targetCoordinates: { x, y, z }, ... }
        if (input.targetCoordinates && 
            typeof input.targetCoordinates.x === 'number' && 
            typeof input.targetCoordinates.y === 'number' && 
            typeof input.targetCoordinates.z === 'number') {
            return {
                type: 'coordinates',
                x: input.targetCoordinates.x,
                y: input.targetCoordinates.y,
                z: input.targetCoordinates.z,
                targetType: input.targetType || input.primaryTarget,
                searchRange: input.searchRange,
                meleeRange: input.meleeRange
            };
        }

        // Handle flat coordinates: { x, y, z }
        if (typeof input.x === 'number' && 
            typeof input.y === 'number' && 
            typeof input.z === 'number') {
            return {
                type: 'coordinates',
                x: input.x,
                y: input.y,
                z: input.z
            };
        }

        // Handle player object: { type: 'player', name: '...' }
        if (input.type === 'player' && input.name) {
            return {
                type: 'player',
                name: input.name
            };
        }

        // Handle player object: { targetType: 'player', primaryTarget: '...' }
        if (input.targetType === 'player' && input.primaryTarget) {
            return {
                type: 'player',
                name: input.primaryTarget,
                searchRange: input.searchRange,
                meleeRange: input.meleeRange
            };
        }

        // Handle landmark object: { name: '...' }
        if (input.name && !input.type) {
            return {
                type: 'landmark',
                name: input.name
            };
        }
    }

    // If input is a string, parse it as before
    if (typeof input === 'string') {
        const coordMatch = input.match(/^(-?\d+\.?\d*)\s*[,\s]\s*(-?\d+\.?\d*)\s*[,\s]\s*(-?\d+\.?\d*)$/);
        if (coordMatch) {
            return {
                type: 'coordinates',
                x: parseFloat(coordMatch[1]),
                y: parseFloat(coordMatch[2]),
                z: parseFloat(coordMatch[3])
            };
        }

        const playerMatch = input.match(/(?:next\s+to\s+)?player\s+(\w+)/i);
        if (playerMatch) {
            return {
                type: 'player',
                name: playerMatch[1]
            };
        }

        return {
            type: 'landmark',
            name: input.trim()
        };
    }

    // Fallback for unexpected types
    return {
        type: 'unknown',
        raw: input
    };
}

const location = parseLocation(input);
return { location };

const status = $input.item.json.location || $input.item.json.position;
return {
  Position: {
    x: Math.floor(status?.x || 0),
    y: Math.floor(status?.y || -60),
    z: Math.floor(status?.z || 0)
  }
}

const targetLocation = $('Teleport Workers').first().json.buildLocation;
const tasks = $input.first().json;
const targetInfo = $('Webhook').first().json.body.targetInfo || {};
const sessionId = $('Webhook').first().json.body.sessionId || 'combat_session';
const COMBAT_RADIUS = 20;
const OFFSET_DISTANCE = 5;
const MIN_TEAMMATE_SPACING = 3;

const rallyPoint = {
  x: Math.floor(targetLocation.x),
  y: Math.floor(targetLocation.y),
  z: Math.floor(targetLocation.z)
};

const getCardinalDirection = (angleRadians) => {
  const normalized = ((angleRadians % (2 * Math.PI)) + 2 * Math.PI) % (2 * Math.PI);
  if (normalized < Math.PI / 4 || normalized >= 7 * Math.PI / 4) return 'east';
  if (normalized < 3 * Math.PI / 4) return 'north';
  if (normalized < 5 * Math.PI / 4) return 'west';
  return 'south';
};

const soldierNames = Object.keys(tasks).sort((a, b) => {
  const numA = parseInt(a.match(/\d+/)?.[0] || 0);
  const numB = parseInt(b.match(/\d+/)?.[0] || 0);
  return numA - numB;
});

const numSoldiers = soldierNames.length;
const updatedTasks = {};

soldierNames.forEach((soldierName, index) => {
  const angleRadians = (index / numSoldiers) * 2 * Math.PI;

  const startX = Math.floor(rallyPoint.x + Math.cos(angleRadians) * OFFSET_DISTANCE);
  const startZ = Math.floor(rallyPoint.z + Math.sin(angleRadians) * OFFSET_DISTANCE);
  const startY = rallyPoint.y;

  const cardinalDirection = getCardinalDirection(angleRadians);
  const otherSoldiers = soldierNames.filter(s => s !== soldierName);

  let task = tasks[soldierName];

  // Update TARGET field
  task = task.replace(
    /TARGET: undefined/,
    `TARGET: Iron Golem`
  );

  // Update POSITION
  const newPosition = `You start ${OFFSET_DISTANCE} blocks ${cardinalDirection} of the target at coordinates (${startX}, ${startY}, ${startZ}).`;
  task = task.replace(
    /POSITION:[\s\S]*?(?=\n\nEQUIPMENT:|EQUIPMENT:)/,
    `POSITION: ${newPosition}\n\n`
  );

  // Add combat zone info
  const combatZoneInfo = `
COMBAT ZONE:
- Your Start Position: (${startX}, ${startY}, ${startZ})
- Rally Point: (${rallyPoint.x}, ${rallyPoint.y}, ${rallyPoint.z})
- Max Chase Distance: ${COMBAT_RADIUS} blocks from rally point
- Your Approach: ${cardinalDirection} side

TEAMMATES: ${otherSoldiers.join(', ') || 'None'}
- Keep ${MIN_TEAMMATE_SPACING}+ blocks from teammates
- Stay on YOUR side of target`;

  if (task.includes('REMINDERS:')) {
    task = task.replace('REMINDERS:', `${combatZoneInfo}\n\nREMINDERS:`);
  } else {
    task += '\n' + combatZoneInfo;
  }

  updatedTasks[soldierName] = task;
});

return {
  tasks: updatedTasks,
  combatMetadata: {
    sessionId: sessionId,
    rallyPoint: rallyPoint,
    combatRadius: COMBAT_RADIUS,
    soldierCount: numSoldiers
  }
};

// Code Node: Generate Combat Tasks from Tactical Plan (NO CODE)

const plan = $('Webhook').first().json.body.combatPlan;
const soldierInstructions = plan.soldierInstructions;
const combatRequest = plan.combatRequest;
const targetInfo = plan.targetInfo;
const battlefieldAssessment = plan.battlefieldAssessment;

let coordinatedTasks = {};

soldierInstructions.forEach((soldier) => {
  const soldierName = soldier.soldierName;
  const objective = soldier.objective;
  const target = soldier.target;
  const positioning = soldier.positioning;
  const tactic = soldier.tactic;
  const healthThreshold = soldier.healthManagement.retreatThreshold;
  const combatDuration = soldier.combatDuration;
  const engagement = soldier.engagement;
  const equipment = soldier.equipment || {};
  const constraints = soldier.constraints || [];
  const instructionText = soldier.instructionText;

  // Format equipment
  const equipmentStr = [
    equipment.weapon ? `Weapon: ${equipment.weapon}` : null,
    equipment.armor ? `Armor: ${equipment.armor}` : null
  ].filter(Boolean).join(', ') || 'Whatever equipped';

  // Format constraints
  const constraintsStr = constraints
    .map(c => `- ${c}`)
    .join('\n');

  // Build task description (plain English, no code)
  coordinatedTasks[soldierName] = `COMBAT MISSION: ${combatRequest}

SOLDIER: ${soldierName}
ROLE: ${soldier.role.toUpperCase()}

OBJECTIVE: ${objective}

TARGET: ${target} (${targetInfo.targetType})

POSITION: Attack from ${positioning}

ENGAGEMENT TIMING: ${engagement.delay === 0 ? 'Engage immediately (no delay)' : `Wait ${engagement.delay}ms before engaging`}

EQUIPMENT: ${equipmentStr}

TACTIC: ${tactic}

BATTLEFIELD:
- Terrain: ${battlefieldAssessment.terrain}
- Hazards: ${battlefieldAssessment.hazards}
- Recommendations: ${battlefieldAssessment.recommendations}

INSTRUCTIONS:
${instructionText}

HEALTH & SAFETY:
- Retreat threshold: ${healthThreshold} HP (${Math.ceil(healthThreshold / 2)} hearts)
- Retreat action: ${soldier.healthManagement.action}
- Maximum combat duration: ${combatDuration} seconds

CONSTRAINTS:
${constraintsStr}

VICTORY CONDITION: ${plan.victoryCondition}
FAILURE CONDITION: ${plan.failureCondition}

SAFETY NOTES: ${plan.safetyNotes}`;
});

return coordinatedTasks;

const status = $input.item.json.location || $input.item.json.position;
return {
  Position: {
    x: Math.floor(status?.x || 0),
    y: Math.floor(status?.y || -60),
    z: Math.floor(status?.z || 0)
  }
}

const myWorkers =  $('Webhook').first().json.body.workers;
const enemyWorkers = $('Bot Workers List').first().json.workers;
const locationData = $input.first().json;  // Location node output


const assignments = myWorkers.map((worker, i) => ({
  myWorker: worker,
  enemyTarget: enemyWorkers[i % enemyWorkers.length],
  buildLocation: locationData.buildLocation,  // From location node
  sessionId: locationData.sessionId,
  role: i === 0 ? 'tank' : 'flanker',
  engageDelay: i === 0 ? 0 : 1500
}));

return [{ json: { assignments } }];

const plan = $('Webhook').first().json.body.combatPlan;
const location = $('Webhook').first().json.body.location || "the target area";

const targetName = plan.targetInfo.target;
const targetType = plan.targetInfo.targetType;
const targetLeader = plan.targetInfo.targetLeader || null;

let coordinatedTasks = {};

plan.soldierInstructions.forEach((soldier) => {
  const soldierRole = soldier.soldierName;

  coordinatedTasks[soldierRole] = `COMBAT MISSION: ${plan.combatRequest}

Location: ${location}
Role: ${soldier.role.toUpperCase()}
Target: ${targetName}${targetLeader ? ` (controlled by ${targetLeader})` : ''}
Target Type: ${targetType}

OBJECTIVE: ${soldier.objective}

INSTRUCTIONS:
${soldier.instructionText}

CONSTRAINTS:
${soldier.constraints.map(c => `- ${c}`).join('\n')}

HEALTH RETREAT: Below ${soldier.healthManagement.retreatThreshold} HP (${Math.floor(soldier.healthManagement.retreatThreshold/2)} hearts)

COMBAT DURATION: ${soldier.combatDuration} seconds max`;
});

return coordinatedTasks;

const assignments = $('Set Targets').first().json.assignments;
const tasks = $input.first().json;
const COMBAT_RADIUS = 20;
const OFFSET_DISTANCE = 5;

const getCardinalDirection = (angleRadians) => {
  const normalized = ((angleRadians % (2 * Math.PI)) + 2 * Math.PI) % (2 * Math.PI);
  if (normalized < Math.PI / 4 || normalized >= 7 * Math.PI / 4) return 'east';
  if (normalized < 3 * Math.PI / 4) return 'north';
  if (normalized < 5 * Math.PI / 4) return 'west';
  return 'south';
};

const updatedTasks = {};
const combatPositions = {};

assignments.forEach((assignment, index) => {
  const soldierName = assignment.myWorker.workerName;
  const enemyTarget = assignment.enemyTarget.name;
  const rallyPoint = assignment.buildLocation;
  const numSoldiers = assignments.length;

  const angleRadians = (index / numSoldiers) * 2 * Math.PI;
  const cardinalDirection = getCardinalDirection(angleRadians);

  const startX = Math.floor(rallyPoint.x + Math.cos(angleRadians) * OFFSET_DISTANCE);
  const startZ = Math.floor(rallyPoint.z + Math.sin(angleRadians) * OFFSET_DISTANCE);
  const startY = rallyPoint.y;

  // Find matching task (by role or index)
  const role = assignment.role.charAt(0).toUpperCase() + assignment.role.slice(1); // "tank" → "Tank"
  const taskKey = Object.keys(tasks).find(key => key.includes(role)) || `Soldier${index + 1}`;
  let task = tasks[taskKey];

  // Append specific target + position info
  const enrichedTask = task + `

ASSIGNED TARGET: ${enemyTarget}
STARTING POSITION: (${startX}, ${startY}, ${startZ}) - ${cardinalDirection} side
RALLY POINT: (${rallyPoint.x}, ${rallyPoint.y}, ${rallyPoint.z})
COMBAT RADIUS: ${COMBAT_RADIUS} blocks from rally point`;

  updatedTasks[soldierName] = enrichedTask;

  combatPositions[soldierName] = {
    startPos: {x: startX, y: startY, z: startZ},
    rallyPoint: rallyPoint,
    assignedTarget: enemyTarget
  };
});

return {
  tasks: updatedTasks,
  combatMetadata: {
    sessionId: assignments[0].sessionId,
    assignments: assignments,
    positions: combatPositions,
    soldierCount: assignments.length
  }
};
